def transform(grid):
    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    from collections import Counter
    counts=Counter(v for row in grid for v in row)
    bg=counts.most_common(1)[0][0]
    # Determine the two edge bars and their horizontal displacement.
    def run_on_edge(r):
        vals=[(c,grid[r][c]) for c in range(w) if grid[r][c]!=bg]
        if len(vals)<3:return None
        # choose longest contiguous run of one non-background color
        best=[]
        for c,v in vals:
            if best and c==best[-1][0]+1 and v==best[-1][1]: best.append((c,v))
            else:
                if len(best)<3: best=[]
                best.append((c,v))
        # enough for these tasks: colored runs are contiguous and distinct from bg
        runs=[]; cur=[]
        for c,v in vals:
            if cur and c==cur[-1][0]+1 and v==cur[-1][1]: cur.append((c,v))
            else:
                if len(cur)>=3:runs.append(cur)
                cur=[(c,v)]
        if len(cur)>=3:runs.append(cur)
        return max(runs,key=len) if runs else None
    top=run_on_edge(0); bot=run_on_edge(h-1)
    if not top or not bot:return out
    delta=(sum(c for c,v in bot)//len(bot))-(sum(c for c,v in top)//len(top))
    bar_colors={v for c,v in top+bot}
    markers=[]
    for r in range(h):
        for c in range(w):
            v=grid[r][c]
            if v!=bg and v not in bar_colors:
                markers.append((r,c,v))
    for r,c,v in markers:
        out[r][c]=4
        # A marker emits a ray toward the top edge; the translated column is
        # projected through the interior between the two edge bars.
        for rr in range(r):
            if grid[rr][c]==bg: out[rr][c]=v
        partner=c+delta
        if 0<=partner<w:
            for rr in range(1,h-1):
                if grid[rr][partner]==bg: out[rr][partner]=v
    return out
